<style>.ff-studio .ff-data-settings{display:grid;gap:20px}.ff-studio .ff-data-group{display:grid;gap:12px;padding-block-start:16px;border-block-start:1px solid var(--ff-line);min-width:0}.ff-studio .ff-data-group h3{font-size:12px;font-weight:650;margin:0;color:#514b80}.ff-studio .ff-data-fields{display:grid;gap:12px;min-width:0}.ff-studio .ff-data-filter{display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:11px;overflow-wrap:anywhere}.ff-studio .ff-data-group summary{cursor:pointer;font-weight:600;font-size:12px;min-height:32px}.ff-studio .ff-data-group .ff-search{margin-top:0}</style>
<style>
.ff-studio .ff-library-tabs{flex-wrap:wrap}
.ff-studio .ff-library-tabs button{flex:1 1 auto;white-space:nowrap}
.ff-studio .ff-data-picker{margin-block-start:16px}
.ff-studio .ff-picker-search{display:flex;align-items:center;gap:4px;border:1px solid var(--ff-line);border-radius:8px;padding:8px;margin-block:16px;background:#fff}
.ff-studio .ff-picker-search:focus-within{outline:2px solid var(--ff-accent);outline-offset:2px}
.ff-studio .ff-picker-search input{min-width:0;inline-size:100%;border:0;background:transparent;outline:0;font:inherit;color:inherit;padding:4px}
.ff-studio .ff-picker-search input::placeholder{color:#596579}
.ff-studio .ff-picker-group{margin-block:24px}
.ff-studio .ff-picker-group h3,.ff-studio .ff-picker-form h3{font-size:12px;font-weight:700;color:#435066;margin-block:0 8px}
.ff-studio .ff-picker-option{display:flex;align-items:center;gap:8px;inline-size:100%;min-block-size:44px;padding:10px 8px;border:0;border-block-end:1px solid var(--ff-line);border-radius:0;background:transparent;text-align:start;font:inherit;color:inherit}
.ff-studio .ff-picker-option:hover{background:#f2f1ff;color:#4338ca}
.ff-studio .ff-picker-option:disabled{opacity:.5;cursor:wait}
.ff-studio .ff-picker-option>span:nth-child(2){flex:1;min-width:0;overflow-wrap:anywhere}
.ff-studio .ff-picker-plus{display:inline-flex;color:var(--ff-accent)}
.ff-studio .ff-picker-plus svg{inline-size:12px;block-size:12px;fill:currentColor}
.ff-studio .ff-picker-launch{inline-size:100%;min-block-size:40px;margin-block:8px;text-align:center;white-space:normal}
.ff-studio .ff-picker-current{display:flex;align-items:center;justify-content:space-between;gap:8px;min-block-size:44px}
.ff-studio .ff-picker-error{color:#9f2420;font-size:12px;line-height:1.8;margin-block:12px}
.ff-studio .ff-picker-status{color:#4338ca;font-size:12px}
.ff-studio .ff-picker-form{margin-block:20px}
.ff-studio .ff-picker-reset{display:block;margin-block:20px}
</style>
<style>.ff-studio .ff-data-advanced>summary{min-block-size:40px;display:list-item;cursor:pointer;color:#435066;font-size:12px;padding-block:10px}.ff-studio .ff-data-advanced[open]>summary{margin-block-end:8px}.ff-studio .ff-picker-current>span{font-size:12px;overflow-wrap:anywhere;line-height:1.8}</style>
